'use strict';

// ─────────────────────────────────────────────────────────────────────────────
// Editor-friendly admin views: clear English field labels, helpful
// descriptions and hidden technical fields. Applied on every start
// (idempotent) by patching the Content-Manager view configurations in the
// core store.
//
// The client only ever touches texts, images, icons and posts — everything
// route-/layout-technical (slugs, keys, hrefs that must match routes, CSS
// object-positions, anchors …) is auto-generated by lifecycles or hidden here.
// Disable with CMS_APPLY_ADMIN_LABELS=false (e.g. to customize views by hand).
// ─────────────────────────────────────────────────────────────────────────────

