async function patchConfiguration(strapi, key, fields) {
  const row = await strapi.db.query('strapi::core-store').findOne({ where: { key } });
  if (!row) return false;
  const value = JSON.parse(row.value);
  const hiddenFields = [];
  const firstFields = [];

  // `__settings` is not a field: it patches the view settings themselves
  // (e.g. defaultSortBy/defaultSortOrder for the list view).
  const { __settings, ...fieldMetas } = fields;
  if (__settings) value.settings = { ...value.settings, ...__settings };

  for (const [field, meta] of Object.entries(fieldMetas)) {
    const m = value.metadatas?.[field];
    if (!m) continue;
    if (meta.hidden) {
      m.edit = { ...m.edit, visible: false };
      hiddenFields.push(field);
      continue;
    }
    if (meta.label) {
      m.edit = { ...m.edit, label: meta.label };
      if (m.list) m.list = { ...m.list, label: meta.label };
    }
    if (meta.description) m.edit = { ...m.edit, description: meta.description };
    if (meta.readonly) m.edit = { ...m.edit, editable: false };
    if (meta.first) firstFields.push(field);
  }

  // hidden fields also disappear from the list-view columns
  if (hiddenFields.length && Array.isArray(value.layouts?.list)) {
    value.layouts.list = value.layouts.list.filter(
      (cell) => !hiddenFields.includes(typeof cell === 'string' ? cell : cell?.name)
    );
  }

  if ((hiddenFields.length || firstFields.length) && Array.isArray(value.layouts?.edit)) {
    const drop = [...hiddenFields, ...firstFields];
    value.layouts.edit = value.layouts.edit
      .map((rowCells) => rowCells.filter((cell) => !drop.includes(cell.name)))
      .filter((rowCells) => rowCells.length > 0);
    // re-insert "first" fields at the very top, full width, in declared order
    for (const field of firstFields.reverse()) {
      value.layouts.edit.unshift([{ name: field, size: 12 }]);
    }
  }

  await strapi.db.query('strapi::core-store').update({
    where: { id: row.id },
    data: { value: JSON.stringify(value) },
  });
  return true;
}

async function applyContentManagerConfig(strapi) {
  if (process.env.CMS_APPLY_ADMIN_LABELS === 'false') return;
  let patched = 0;
  for (const [uid, fields] of Object.entries(CONTENT_TYPES)) {
    if (await patchConfiguration(strapi, `plugin_content_manager_configuration_content_types::${uid}`, fields)) patched++;
    else strapi.log.warn(`[admin-labels] no configuration found for ${uid}`);
  }
  for (const [uid, fields] of Object.entries(COMPONENTS)) {
    if (await patchConfiguration(strapi, `plugin_content_manager_configuration_components::${uid}`, fields)) patched++;
    else strapi.log.warn(`[admin-labels] no configuration found for component ${uid}`);
  }
  strapi.log.info(`[admin-labels] applied editor labels/visibility to ${patched} views`);
}

module.exports = { applyContentManagerConfig };
